import{bQ as e,aL as a,u as r,G as n}from"./chunks/framework.C1gZXFVa.js";const g=JSON.parse('{"title":"保证金与资金协同","description":"现货与合约账户划转、追加/减少保证金如何进入撮合热钱包，与开平仓串行争用同一份权益。","frontmatter":{"title":"保证金与资金协同","description":"现货与合约账户划转、追加/减少保证金如何进入撮合热钱包，与开平仓串行争用同一份权益。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/080505"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/080505"}],["meta",{"property":"og:title","content":"保证金与资金协同 · TGEX"}],["meta",{"property":"og:description","content":"现货与合约账户划转、追加/减少保证金如何进入撮合热钱包，与开平仓串行争用同一份权益。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"保证金与资金协同 · TGEX"}],["meta",{"name":"twitter:description","content":"现货与合约账户划转、追加/减少保证金如何进入撮合热钱包，与开平仓串行争用同一份权益。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"保证金与资金协同\\",\\"description\\":\\"现货与合约账户划转、追加/减少保证金如何进入撮合热钱包，与开平仓串行争用同一份权益。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/080505\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/080505\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/080505.md","filePath":"08.合约手册/05.核心流程/05.保证金与资金协同.md"}'),d={name:"pages/080505.md"};function s(o,t,p,i,h,l){return a(),r("div",null,[...t[0]||(t[0]=[n('<div class="doc-eyebrow">合约手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="保证金与资金协同" tabindex="-1">保证金与资金协同 <a class="header-anchor" href="#保证金与资金协同" aria-label="Permalink to &quot;保证金与资金协同&quot;">​</a></h1><div class="doc-lead">合约开仓占用的是**合约账户**里的保证金，不是现货钱包里的可用余额直接划走。划转与加减保证金必须进入撮合改账通道，才能与持仓占用保持一致。</div><p>资金语义总览见<a href="/pages/0602">核心资金流程</a>；合约热钱包见<a href="/pages/080802">用户合约账户缓存</a>。</p><h2 id="为什么要协同" tabindex="-1">为什么要协同 <a class="header-anchor" href="#为什么要协同" aria-label="Permalink to &quot;为什么要协同&quot;">​</a></h2><p>若只改账务库或现货侧余额、不通知合约撮合：</p><ul><li>用户以为已转入合约，开仓仍报可用不足</li><li>或热钱包已加钱、账务未对齐 → 对账困难</li></ul><p>因此划转、充提到合约侧、追加 / 减少保证金，都应变成撮合可串行处理的改账 / 调保证金事件。</p><h2 id="常见路径" tabindex="-1">常见路径 <a class="header-anchor" href="#常见路径" aria-label="Permalink to &quot;常见路径&quot;">​</a></h2><p><strong>现货 ↔ 合约划转（语义）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>账务 / 划转确认 → 消息 → 合约撮合改合约钱包可用 → 异步流水落库</span></span></code></pre></div><p><strong>追加 / 减少保证金</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户申请加 / 减保证金 → 委托或账户门面 → 撮合校验持仓与维持要求 → 改占用与可用</span></span></code></pre></div><p>减保证金前必须检查：减完后是否仍满足维持要求、是否与未成交开平仓冲突。不满足则拒绝，而不是先减再等强平。</p><h2 id="和开平仓的关系" tabindex="-1">和开平仓的关系 <a class="header-anchor" href="#和开平仓的关系" aria-label="Permalink to &quot;和开平仓的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>谁改热钱包 / 持仓</th><th>是否进订单簿</th></tr></thead><tbody><tr><td>开仓占用 / 平仓释放</td><td>交易事件</td><td>是</td></tr><tr><td>划转入金 / 出金</td><td>改账事件</td><td>否</td></tr><tr><td>加 / 减保证金</td><td>调保证金接口 / 事件</td><td>否</td></tr><tr><td>强平清算</td><td>强平事件</td><td>系统单</td></tr></tbody></table><p>开平仓同步主链<strong>不堵</strong>在「等划转完成」的用户接口上；但没划进合约账户就开不了仓——这是账户余额事实，不是链路设计矛盾。</p><h2 id="本文边界" tabindex="-1">本文边界 <a class="header-anchor" href="#本文边界" aria-label="Permalink to &quot;本文边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对照</th><th>说明</th></tr></thead><tbody><tr><td><a href="/pages/080501">开仓主流程</a></td><td>占用已在合约账户中的保证金</td></tr><tr><td><a href="/pages/080503">强平与清算</a></td><td>风险结果改同一钱包</td></tr><tr><td><a href="/pages/0603">对账与资金一致性</a></td><td>跨账户核对</td></tr><tr><td>链上充提</td><td>见<a href="/pages/1003">钱包 · 核心充提流程</a>；到合约账户仍须本页协同</td></tr><tr><td>资金费定期结算</td><td>旁路结算，费率源以产品为准，不在此写死排期</td></tr></tbody></table><p>同组：<a href="/pages/080802">用户合约账户缓存</a> · <a href="/pages/0802">系统架构</a> · <a href="/pages/0602">核心资金流程</a></p>',20)])])}const m=e(d,[["render",s]]);export{g as __pageData,m as default};
